    check(validate_marriage_source_catalog(catalog,*common,interactions).ok,"explicit unknown origin rejected as missing");auto quote=preview_marriage_statement(store,meeting,interactions,access,catalog,"listener","proposal");check(quote.ok,"actual original-person node not read");check(catalog.origins.find("listener")->status=="unknown","source silently declared unknown person unmarried");check(revalidate_marriage_statement(store,meeting,interactions,access,catalog,quote.value).ok,"same source changed");check(compare_boundary(snapshot,encode_common_state(store.state())).exact(),"source read mutated world");
    auto other=catalog;other.origins.find("speaker")->status="married";other.origins.find("speaker")->spouse_actor_id="listener";check(!validate_marriage_source_catalog(other,*common,interactions).ok,"one-sided origin marriage accepted");other.origins.find("listener")->status="married";other.origins.find("listener")->spouse_actor_id="speaker";check(validate_marriage_source_catalog(other,*common,interactions).ok,"reciprocal authored original marriage rejected");other.statements.find("proposal")->intent="transfer_assets";check(!validate_marriage_source_catalog(other,*common,interactions).ok,"unsupported intent became marriage");
    check(!preview_marriage_statement(store,meeting,interactions,access,catalog,"speaker","proposal").ok,"player signed other listener");meeting.interactions[0].node_id="end";check(!revalidate_marriage_statement(store,meeting,interactions,access,catalog,quote.value).ok,"left original node retained current consent");meeting.interactions[0].node_id="offer";store.state().actors.find("speaker")->birth_tick=21-18*720;check(!preview_marriage_statement(store,meeting,interactions,access,catalog,"listener","proposal").ok,"under18 statement accepted");store.state().actors.find("speaker")->birth_tick=20-18*720;
    auto saved=encode_marriage_statement_source(quote.value.statement);auto decoded=decode_marriage_statement_source(saved);check(decoded.ok&&marriage_statement_equal(decoded.value,quote.value.statement),"JSON source roundtrip");auto duplicate=saved;duplicate.find("context")->as<BoundaryValue::Dict>()->emplace_back("provider_actor_id",BoundaryValue{"other"});check(!decode_marriage_statement_source(duplicate).ok,"nested duplicate provider accepted");duplicate=saved;duplicate.as<BoundaryValue::Dict>()->emplace_back("intent",BoundaryValue{"accept_dissolution"});check(!decode_marriage_statement_source(duplicate).ok,"duplicate intent accepted");
