    store.state().identity.tick=30;store.state().identity.revision=9;store.state().identity.execution_epoch=99;store.state().actors.find("speaker")->alive=false;store.state().actors.find("speaker")->available=false;check(validate_marriage_statement_source(store.state(),*common,interactions,catalog,cold).ok,"later death erased genuine past statement");check(!revalidate_marriage_statement(store,meeting,interactions,access,catalog,quote.value).ok,"old predeath quote remained current");cold.world_id[0]=4;check(!validate_marriage_statement_source(store.state(),*common,interactions,catalog,cold).ok,"other world source accepted");
